function employee_scope69(array $ids,int $selected):array {return $selected>0?array_values(array_filter($ids,fn($id)=>(int)$id===$selected)):$ids;}
function v26_setting(string $key,mixed $value):void {query('MERGE INTO ep_settings WITH (HOLDLOCK) AS target USING (VALUES (?, ?)) AS source (setting_key, value_json) ON target.setting_key=source.setting_key WHEN MATCHED THEN UPDATE SET value_json=source.value_json WHEN NOT MATCHED THEN INSERT (setting_key, value_json) VALUES (source.setting_key, source.value_json);',[$key,jencode($value)]);}
