function v26_audit_clean(array $v):array {foreach($v as $k=>$x){if(preg_match('/password|pass|token|nonce|secret|csrf|key/i',(string)$k)){unset($v[$k]);continue;}if(is_array($x))$v[$k]=v26_audit_clean($x);}return $v;}
function v26_audit_before(string $action,array $b):?array {if(empty($b['id']))return null;$table=$action==='v26_history_correct'?'ep_history':($action==='v26_payment'?match($b['kind']??''){'bank','recovery'=>'ep_bank_payroll','payroll'=>'ep_payroll',default=>'ep_records'}:match(true){str_starts_with($action,'user_')=>'ep_users',str_contains($action,'payroll')=>'ep_payroll',str_starts_with($action,'bank_')=>'ep_bank_payroll',str_starts_with($action,'company_')=>'ep_companies',str_starts_with($action,'record_'),str_starts_with($action,'v26_')=>'ep_records',default=>null});if(!$table)return null;$r=query('SELECT * FROM '.$table.' WHERE id=?',[(int)$b['id']])->fetch();return $r?v26_audit_clean($r):null;}
function v26_alerts_run():array {$batch=bin2hex(random_bytes(12));$cfg=settings();$today=local_time()->format('Y-m-d');$sent=0;$failed=0;foreach(query("SELECT * FROM ep_users WHERE role<>'admin'")->fetchAll()as $s){try{$x=v26_leave_balance((int)$s['id'],$cfg,$today);if(empty($x['flags']['employed'])||!$x['flags']['leave_days'])continue;$level=$x['remaining']>=($cfg['leave_alert_high']??60)?2:($x['remaining']>=($cfg['leave_alert_first']??30)?1:0);$key='leave_alert_'.(int)$s['id'];$old=json_decode(query('SELECT value_json FROM ep_settings WHERE setting_key=?',[$key])->fetchColumn()?:'0',true);if($level>$old){foreach(array_column(supervisor_recipients32(),'id')as $admin)notice((int)$admin,'متابعة رصيد الإجازات',$s['name'].' — رصيد الأيام '.number_format($x['remaining'],6).' — مستوى '.$level,false,['category'=>'leave','type'=>'balance','batch'=>$batch,'balance'=>$x['remaining'],'level'=>$level,'employee_code'=>employee_key($s),'employee_id'=>(int)$s['id'],'screen'=>'leave_overview']);$sent++;}v26_setting($key,$level);}catch(Throwable $e){$failed++;security_log($e,'leave_alert');}}return ['sent'=>$sent,'failed'=>$failed,'date'=>$today];}

function v26_money_validate(array $data):void {foreach($data as $key=>$value){if(is_array($value)){v26_money_validate($value);continue;}if(in_array((string)$key,['sales_agent_deduction36','collection_deduction36','amount','salary','bank_salary','rate','telephone','transport','housing','other'],true)&&$value!==''&&$value!==null){if(!is_numeric($value)||!is_finite((float)$value)||abs((float)$value*1000-round((float)$value*1000))>0.000001)fail('المبالغ تقبل3 منازل عشرية فقط');}}}

function payout_held(array $staff,?string $date=null):bool{$date=$date??local_time()->format('Y-m-d');$rows=query("SELECT * FROM ep_records WHERE user_id=? AND module='payout_status' AND status='approved' ORDER BY date_from DESC,id DESC",[$staff['id']])->fetchAll();foreach($rows as $row)if($row['date_from']<=$date&&(!$row['date_to']||$row['date_to']>=$date))return (bool)(decode($row['body_json'])['held']??false);return (bool)(decode($staff['profile_json'])['payout_on_hold']??false);}
function v26_cash_integrity(int $uid):void{$s=employee_required($uid);$latest=local_time()->format('Y-m-d');foreach(query("SELECT date_from FROM ep_records WHERE user_id=? AND module='leave_cash' AND status='approved'",[$uid])->fetchAll()as $row)$latest=max($latest,$row['date_from']);$b=v26_leave_balance($uid,settings(),$latest);if(empty($b['cash_ledger_valid']))fail('توجد حركة صرف تجعل الرصيد المالي غير صالح؛ لم تعتمد العملية');}
